import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CContainer, CInput, CRow } from '@coreui/react';
import { requestHeaderGETWithAuth, requestHeaderPUTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "ViewInternetTenant.js";

class ViewInternetTenant extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            internetTenant: null,
            error: null,
            isEditing: false,
            editName: '',
            editBaseDomain: '',
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "View Internet Tenant";
        this.fetchInternetTenant();
    }

    fetchInternetTenant() {
        const internetTenantId = this.props.match.params.internetTenantId;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/internet-tenant/' + internetTenantId;

        this.setState({ isLoaded: false });

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchInternetTenant", "SUCCESS", "result", result);
            this.setState({ isLoaded: true, internetTenant: result.data });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchInternetTenant", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    startEditing = () => {
        const { internetTenant } = this.state;
        this.setState({ isEditing: true, editName: internetTenant.name, editBaseDomain: internetTenant.baseDomain });
    }

    cancelEditing = () => {
        this.setState({ isEditing: false });
    }

    saveChanges = () => {
        const { internetTenant, editName, editBaseDomain } = this.state;
        const payload = { name: editName, baseDomain: editBaseDomain };

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/internet-tenant/' + internetTenant.id;

        fetch(API_URL, requestHeaderPUTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "saveChanges", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1, internetTenant: result.data, isEditing: false });
            setTimeout(() => this.setState({ loadingModalVisible: false, loadingModalState: 0 }), 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "saveChanges", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    render() {
        const { isLoaded, error, isEditing } = this.state;

        if (!isLoaded) return <Loading />;

        if (error) {
            return (
                <div style={{ textAlign: 'center', padding: '40px', color: '#dc3545' }}>
                    <h3>Error loading internet tenant</h3>
                    <p>{error}</p>
                    <a href="#/internet-tenants">← Back</a>
                </div>
            );
        }

        return (
            <div>
                <a href="#/internet-tenants" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Internet Tenants List</CButton>
                </a>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="6">
                            <CCard className="p-4">
                                <CCardBody>
                                    {!isEditing ? this.renderViewMode() : this.renderEditMode()}
                                </CCardBody>
                            </CCard>
                        </CCol>
                    </CRow>
                </CContainer>
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }

    renderViewMode() {
        const { internetTenant } = this.state;

        return (
            <>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h1>🌐 {internetTenant.name}</h1>
                    <div style={{ display: 'flex', gap: '8px' }}>
                        <CButton color="secondary" onClick={() => this.fetchInternetTenant()} title="Refresh">🔄</CButton>
                        <CButton color="primary" onClick={this.startEditing}>✏️ Edit</CButton>
                    </div>
                </div>
                <hr />
                <div style={{ marginBottom: '12px' }}>
                    <h5>🆔 ID</h5>
                    <p>{internetTenant.id}</p>
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <h5>🌐 Base Domain</h5>
                    <p>{internetTenant.baseDomain}</p>
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <h5>🕐 Created</h5>
                    <p>{internetTenant.createdAt ? new Date(internetTenant.createdAt).toLocaleString() : '—'}</p>
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <h5>🔄 Last Updated</h5>
                    <p>{internetTenant.updatedAt ? new Date(internetTenant.updatedAt).toLocaleString() : '—'}</p>
                </div>
            </>
        );
    }

    renderEditMode() {
        const { editName, editBaseDomain } = this.state;

        return (
            <>
                <h2>✏️ Edit Internet Tenant</h2>
                <hr />
                <div style={{ marginBottom: '12px' }}>
                    <label><strong>Name *</strong></label>
                    <CInput
                        value={editName}
                        onChange={(e) => this.setState({ editName: e.target.value })}
                        required
                    />
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <label><strong>Base Domain *</strong></label>
                    <CInput
                        value={editBaseDomain}
                        placeholder="e.g. acme.com (no slashes)"
                        onChange={(e) => this.setState({ editBaseDomain: e.target.value })}
                        required
                    />
                </div>
                <hr />
                <div style={{ display: 'flex', gap: '12px' }}>
                    <CButton color="success" onClick={this.saveChanges}>💾 Save</CButton>
                    <CButton color="secondary" onClick={this.cancelEditing}>Cancel</CButton>
                </div>
            </>
        );
    }
}

export default ViewInternetTenant;
